INSERT INTO collection_pages VALUES('14c5d0c331b6360afab7e6aca617e4606fbcf83dac7acdf93c7ead038c287556','554a9628a83fa9b7a4ef01d44f373903c0cb3cf1a30e0727185de251b95a7f60','{"hasNext":false,"items":[{"author":{"account":null,"email":"apple@Manasas-MacBook-Pro.local","name":"Manasa Ellanti"},"authoredDate":"2026-04-29T14:12:52Z","committedDate":"2026-04-29T14:12:52Z","committer":{"account":null,"email":"apple@Manasas-MacBook-Pro.local","name":"Manasa Ellanti"},"observedAt":"2026-10-08T22:49:05.818Z","repositoryId":1224037754,"sha":"309bede6e90f612e5437fe8d83c5f89b08f657dc"}],"observedAt":"2026-10-08T22:49:05.818Z","raw":[{"author":null,"comments_url":"https://api.github.com/repos/ellantimanasa-source/Final-project/commits/309bede6e90f612e5437fe8d83c5f89b08f657dc/comments","commit":{"author":{"date":"2026-04-29T14:12:52Z","email":"apple@Manasas-MacBook-Pro.local","name":"Manasa Ellanti"},"comment_count":0,"committer":{"date":"2026-04-29T14:12:52Z","email":"apple@Manasas-MacBook-Pro.local","name":"Manasa Ellanti"},"message":"Initial commit: scam-vs-personality voice demo\n\nA simulated phone call between two AI characters: a card-phishing scammer\nand a personality (Miranda Priestly, Ronny Chieng, or Trevor Noah) playing\nthe target. Audio in 24 kHz PCM throughout; transcripts on screen.\n\n- Node/Express + WebSocket server runs an alternating turn loop. Each\n  side has its own POV history so neither character \"speaks both roles.\"\n- Text generation: gemini-2.5-flash (regular API), thinking disabled so\n  responses are full sentences instead of 3-word stubs.\n- Voices are layered by availability:\n    * Scammer       -> Gemini TTS (Orus)\n    * Personality   -> ElevenLabs (cloned voice) > OpenAI > Gemini TTS\n- Browser uses an AudioWorklet for buffered 24 kHz PCM playback so all\n  three TTS backends drop into the same player.\n- Server estimates each clip''s duration from PCM length and paces turns\n  so the call sounds real, not like a debate.\n\nMade-with: Cursor","tree":{"sha":"9515f00a66b29cd0966395171a2fd6dc1cf0f007","url":"https://api.github.com/repos/ellantimanasa-source/Final-project/git/trees/9515f00a66b29cd0966395171a2fd6dc1cf0f007"},"url":"https://api.github.com/repos/ellantimanasa-source/Final-project/git/commits/309bede6e90f612e5437fe8d83c5f89b08f657dc","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/ellantimanasa-source/Final-project/commit/309bede6e90f612e5437fe8d83c5f89b08f657dc","node_id":"C_kwDOSPVVetoAKDMwOWJlZGU2ZTkwZjYxMmU1NDM3ZmU4ZDgzYzVmODliMDhmNjU3ZGM","parents":[],"sha":"309bede6e90f612e5437fe8d83c5f89b08f657dc","url":"https://api.github.com/repos/ellantimanasa-source/Final-project/commits/309bede6e90f612e5437fe8d83c5f89b08f657dc"}],"requestUrl":"https://api.github.com/repos/ellantimanasa-source/Final-project/commits?per_page=100&page=1&sha=309bede6e90f612e5437fe8d83c5f89b08f657dc&since=2025-03-31T23%3A59%3A59.000Z&until=2026-10-08T16%3A24%3A45.941Z"}');
